"""
Entry point: runs the full experiment suite (all 12 required experiments,
parameter sweeps, heatmaps, Model A/B comparison, fine-tuning scan, and
automatically generated conclusions) and writes docs/results.md.

Usage:
    python main.py
"""

import sys
import time

sys.path.insert(0, ".")

from src.simulation.run_experiments import run_all_experiments  # noqa: E402


def write_results_doc(evidence: dict) -> None:
    exp = evidence["_experiment_results_for_docs"]
    lines = []
    lines.append("# Results\n")
    lines.append(
        "Auto-generated by `main.py`. All numbers below come directly from the "
        "simulation runs in `results/data/`; nothing here has been hand-edited "
        "or hand-tuned after the fact. See `docs/model_description.md` and "
        "`docs/equations.md` for what these numbers mean physically, and "
        "`docs/physics_limitations.md` for what they do NOT mean.\n"
    )

    lines.append("## Headline experiment results\n")
    lines.append("| Experiment | eta (final) | Outcome |")
    lines.append("|---|---|---|")
    lines.append(f"| 1. Model A baseline | {evidence['experiment_1']['eta_final']:.6g} | "
                  f"{evidence['experiment_1']['outcome']} |")
    lines.append(f"| 2. Pre-BB dark sector, zero coupling | "
                  f"{evidence['experiment_2']['eta_final']:.6g} | (dark survival = "
                  f"{evidence['experiment_2']['dark_survival_fraction']:.4g}) |")
    lines.append(f"| 3. Pre-BB dark sector, R=1 (equal coupling) | "
                  f"{evidence['experiment_3']['eta_final']:.6g} | dark depleted: "
                  f"{evidence['experiment_3']['N_dark_depleted']} |")
    lines.append(f"| 4. Pre-BB dark sector, R=4 | "
                  f"{evidence['experiment_4']['eta_final']:.6g} | |")
    lines.append(f"| 9. CP violation OFF (R forced to 1) | "
                  f"{evidence['sakharov_ablation']['cp_off_eta']:.6g} | |")
    lines.append(f"| 10. Baryon-number violation OFF | "
                  f"{evidence['sakharov_ablation']['bviol_off_eta']:.6g} | |")
    lines.append(f"| 11. Full thermal equilibrium (washout) | "
                  f"{evidence['sakharov_ablation']['equilibrium_eta']:.6g} | |")
    lines.append(f"| 12. Departure from equilibrium | "
                  f"{evidence['sakharov_ablation']['non_equilibrium_eta']:.6g} | |")
    lines.append("")

    lines.append("## R sweep (sigma_DM_matter / sigma_DM_antimatter)\n")
    rsw = evidence["R_sweep"]
    lines.append(f"eta varies with R: **{rsw['eta_varies_with_R']}**. "
                  f"eta range across the sweep: {rsw['eta_range']}. "
                  f"See `results/plots/eta_vs_R.png` and "
                  f"`results/data/experiment_04_R_sweep.csv`.\n")

    lines.append("## Survival-fraction sweep\n")
    ssw = evidence["survival_fraction_sweep"]
    lines.append(f"eta is exactly zero at survival_fraction=0: "
                  f"**{ssw['eta_zero_at_zero_survival']}**. "
                  f"See `results/plots/eta_vs_survival_fraction.png`.\n")

    lines.append("## Outcome gallery\n")
    lines.append(
        "Demonstrates that the simulation can produce every qualitatively "
        "distinct behavior required by the project spec, from explicit "
        "parameter choices (none of these are hard-coded outcomes):\n"
    )
    lines.append("| Scenario | eta (final) | Outcome | Dark survival fraction |")
    lines.append("|---|---|---|---|")
    for row in evidence["outcome_gallery"]:
        dsf = row["dark_survival_fraction"]
        dsf_str = f"{dsf:.4g}" if dsf is not None else "n/a"
        lines.append(f"| {row['label']} | {row['eta_final']:.4g} | {row['outcome']} | {dsf_str} |")
    lines.append("")

    lines.append("## Sakharov-condition ablation\n")
    sk = evidence["sakharov_ablation"]
    lines.append(
        f"- Baseline (all 3 conditions satisfied, R=4): eta = {sk['baseline_eta']:.6g}\n"
        f"- CP violation OFF (R forced to 1): eta = {sk['cp_off_eta']:.6g}\n"
        f"- Baryon-number violation OFF: eta = {sk['bviol_off_eta']:.6g}\n"
        f"- Full thermal equilibrium (washout): eta = {sk['equilibrium_eta']:.6g}\n"
        f"- Departure from equilibrium (freeze-out): eta = {sk['non_equilibrium_eta']:.6g}\n"
    )
    lines.append("See `results/plots/sakharov_ablation_bar.png`.\n")

    lines.append("## Fine-tuning scan\n")
    ft = evidence["fine_tuning_summary"]
    lines.append(
        f"n = {ft['n_samples']} samples (seeded, reproducible). "
        f"{ft['fraction_negligible_asymmetry']:.1%} negligible asymmetry, "
        f"{ft['fraction_interesting_intermediate_asymmetry']:.1%} non-trivial "
        f"persistent intermediate asymmetry, "
        f"{ft['fraction_saturated_extreme_asymmetry']:.1%} saturated/extreme. "
        f"See `results/plots/fine_tuning_eta_histogram.png` and "
        f"`results/data/fine_tuning_scan.csv`.\n"
    )

    lines.append("## Model A vs Model B\n")
    lines.append(evidence["model_comparison"]["summary"] + "\n")

    lines.append("## Conservation checks\n")
    cons = evidence["experiment_1"]["conservation"]
    lines.append(
        f"Model A energy-conservation residual (max, relative): "
        f"{cons['max_abs_energy_conservation_residual_relative']:.3e} "
        f"(solver-precision level, confirms the ODE bookkeeping in "
        f"`src/simulation/ode_system.py` is internally consistent -- see "
        f"`src/analysis/conservation_checks.py` for exactly what this checks "
        f"and does not check).\n"
    )

    lines.append("---\n")
    lines.append(evidence["_conclusions_markdown"])

    with open("docs/results.md", "w", encoding="utf-8") as f:
        f.write("\n".join(lines))


if __name__ == "__main__":
    t0 = time.time()
    evidence = run_all_experiments()
    write_results_doc(evidence)
    print(f"\nDone in {time.time() - t0:.1f}s. See docs/results.md, results/plots/, "
          f"results/heatmaps/, results/data/.")
